const staleViewings = `-- name: StaleViewings :many
SELECT id FROM viewing_requests WHERE status IN ('REQUESTED','RESCHEDULED') AND ends_at < $1 ORDER BY ends_at LIMIT $2
`

type StaleViewingsParams struct {
	EndsAt time.Time
	Limit  int32
}

func (q *Queries) StaleViewings(ctx context.Context, db DBTX, arg StaleViewingsParams) ([]ids.ID, error) {
	rows, err := db.Query(ctx, staleViewings, arg.EndsAt, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ids.ID
	for rows.Next() {
		var id ids.ID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

